import {defineCollection, z} from 'astro:content';
import {glob} from 'astro/loaders';

/**
 * Posts generated by medmark.
 *
 * The default medmark template writes one folder per slug containing an
 * `index.md`, so the id of `my-post/index.md` is normalised back to `my-post`.
 *
 * The schema is deliberately lenient: every field is optional and unknown
 * front matter keys are passed through, so custom medmark templates keep
 * working without touching this file.
 */
const posts = defineCollection({
  loader: glob({
    base: './content/posts',
    generateId: ({entry}) => entry.replace(/\/index\.mdx?$/, '').replace(/\.mdx?$/, ''),
    pattern: '**/*.{md,mdx}',
  }),
  schema: z
    .object({
      authors: z.array(z.union([z.string(), z.object({name: z.string().optional()}).passthrough()])).optional(),
      bannerImage: z.string().optional(),
      categories: z.array(z.string()).optional(),
      date: z.coerce.date().optional(),
      description: z.string().optional(),
      draft: z.boolean().optional(),
      images: z.array(z.string()).optional(),
      ogImage: z.string().optional(),
      readingTime: z.union([z.string(), z.number()]).optional(),
      slug: z.string().optional(),
      tags: z.array(z.string()).optional(),
      title: z.string().optional(),
    })
    .passthrough(),
});

export const collections = {posts};
